"""Render reports/*.json into REPORT.md: experiments, operational findings,
and the production-replay monitoring results, for team review."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
R = ROOT / "reports"


def pct(x):
    return f"{x * 100:.1f}%"


def main():
    exp = json.loads((R / "experiments.json").read_text())
    ins = json.loads((R / "insights.json").read_text())
    mon = json.loads((R / "monitoring.json").read_text()) if (R / "monitoring.json").exists() else None

    out = ["# Late-delivery risk: results", "",
           "Generated by `python src/report.py` from `reports/*.json`. Every run is also in MLflow "
           "(`mlflow ui --backend-store-uri sqlite:///mlflow.db`).", "",
           "## 1. Experiments (validation = Jan-Mar 2018)", "",
           "| Model | ROC AUC | PR AUC | Late orders caught in top 10% | Precision in top 10% |",
           "|---|---|---|---|---|"]
    for name, v in exp.items():
        if name == "final":
            continue
        m = v["valid"]
        out.append(f"| {name} | {m['roc_auc']:.3f} | {m['pr_auc']:.3f} | {pct(m['recall_at_10pct'])} "
                   f"| {pct(m['precision_at_10pct'])} |")

    f = exp["final"]
    t, rb = f["test"], f["test_rule_baseline"]
    out += ["", f"**Chosen:** `{f['model']}` (best validation PR AUC), refit on train+valid, scored once "
            "on the untouched Apr-Aug 2018 test months.", "",
            "| Test (Apr-Aug 2018) | ROC AUC | Late orders caught in top 10% | Lift |", "|---|---|---|---|",
            f"| {f['model']} | {t['roc_auc']:.3f} | {pct(t['recall_at_10pct'])} | {t['lift_at_10pct']:.2f}x |",
            f"| seller-history rule | {rb['roc_auc']:.3f} | {pct(rb['recall_at_10pct'])} | {rb['lift_at_10pct']:.2f}x |",
            "", "Why the linear model won: the late rate swings from 1.4% to 21% month to month "
            "(Black Friday 2017, Feb-Mar 2018). The tree models fit 2017's patterns closely and "
            "generalized worse to 2018; the regularized linear model ranked more stably.", ""]

    out += ["## 2. Operational findings (SQL, `src/insights.py`)", ""]
    rev = {r["is_late"]: r for r in ins["review_by_lateness"]}
    out.append(f"- Late orders average **{rev[1]['avg_review']}** stars vs **{rev[0]['avg_review']}** on time; "
               f"{rev[1]['pct_1_2_star']}% of late orders get a 1-2 star review vs {rev[0]['pct_1_2_star']}%.")
    route = {r["route"]: r["late_pct"] for r in ins["late_rate_by_route"]}
    out.append(f"- Cross-state orders run late {route['cross state']}% of the time vs {route['same state']}% within a state.")
    worst = ins["late_rate_by_customer_state"][0]
    out.append(f"- Worst destination state with 500+ orders: {worst['customer_state']} at {worst['late_pct']}% late.")
    out.append("")

    if mon:
        out += ["## 3. Monitoring: production replay (Apr-Aug 2018 through the live API)", "",
                "| Month | Orders | Late rate | ROC AUC | Flag recall | Flag precision | Drifted inputs (PSI > 0.25) |",
                "|---|---|---|---|---|---|---|"]
        for month, p in mon["performance"].items():
            d = mon["drift"].get(month, {})
            out.append(f"| {month} | {p['n']} | {pct(p['late_rate'])} | {p['roc_auc']:.3f} | "
                       f"{pct(p['flag_recall'])} | {pct(p['flag_precision'])} | {', '.join(d.get('drifted', [])) or 'none'} |")
        out += ["", "Score PSI rose from Apr to Aug while the fixed threshold flagged a growing share of "
                "orders (design target 10%): retrain when either alarm fires.", ""]

    (ROOT / "REPORT.md").write_text("\n".join(out), encoding="utf-8")
    print("\n".join(out))


if __name__ == "__main__":
    main()
